do $$ declare b_id uuid; v2 uuid; rl_id uuid; ing_id uuid; ing_unit uuid; order_id uuid; order_line_id uuid; begin select pb.id,pb.order_id,pb.order_line_id into b_id,order_id,order_line_id from production_batches pb where pb.business_code='PB-000002'; select rv.id into v2 from recipe_versions rv join recipes r on r.id=rv.recipe_id where r.name='TEST ONLY — Vangi Bath Powder Production Recipe' and rv.version_number=2; select rl.id,rl.ingredient_item_id,rl.unit_id into rl_id,ing_id,ing_unit from recipe_lines rl where rl.recipe_version_id=v2 limit 1; if b_id is null or v2 is null or rl_id is null then return; end if; delete from production_batch_plan_lines where production_batch_id=b_id; insert into production_batch_plan_lines(production_batch_id,recipe_line_id,ingredient_item_id,planned_quantity,unit_id) values(b_id,rl_id,ing_id,0.025,ing_unit); update stock_reservations set quantity_reserved=0.025,unit_id=ing_unit,status='active',updated_at=now() where production_batch_id=b_id and status='active'; update production_batches set recipe_version_id=v2,planned_output_quantity=50,wife_approval_status='pending',status='planned',updated_at=now() where id=b_id; end $$;
